// Hand-written `@hono/zod-validator` stub for the flowatlas fixture suite:
// middleware that checks one part of a request against a schema, and types
// what the handler behind it is handed for that part.

import type { MiddlewareHandler } from 'hono';
import type { ZodType } from 'zod';

export declare function zValidator<
  T extends 'json' | 'query' | 'param' | 'header' | 'form',
  S extends ZodType<any>,
>(target: T, schema: S): MiddlewareHandler<{ out: { [K in T]: S['_output'] } }>;
